package com.chatserver.ratelimit

import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicLong
import java.time.Instant
import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64

data class TokenClaims(
    val userId: String,
    val serviceId: String,
    val issuedAt: Long,
    val sessionNonce: String
)

class RateLimitBucket(private val maxTokens: Int, private val refillRatePerSec: Double) {
    private var tokens: Double = maxTokens.toDouble()
    private var lastRefill: Long = System.nanoTime()

    @Synchronized
    fun tryConsume(): Boolean {
        refill()
        if (tokens >= 1.0) {
            tokens -= 1.0
            return true
        }
        return false
    }

    private fun refill() {
        val now = System.nanoTime()
        val elapsed = (now - lastRefill) / 1_000_000_000.0
        tokens = minOf(maxTokens.toDouble(), tokens + elapsed * refillRatePerSec)
        lastRefill = now
    }
}

object HmacValidator {
    private val SECRET = System.getenv("AUTH_HMAC_SECRET") ?: "default-dev-secret-key-32bytes!!"

    fun validateServiceToken(token: String): TokenClaims? {
        val parts = token.split(".")
        if (parts.size != 3) return null
        val header = parts[0]
        val payload = parts[1]
        val signature = parts[2]

        val expectedSig = computeHmac("$header.$payload")
        if (!timingSafeEquals(signature, expectedSig)) return null

        val decoded = String(Base64.getUrlDecoder().decode(payload))
        return parsePayload(decoded)
    }

    private fun computeHmac(data: String): String {
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(SECRET.toByteArray(), "HmacSHA256"))
        return Base64.getUrlEncoder().withoutPadding().encodeToString(mac.doFinal(data.toByteArray()))
    }

    private fun timingSafeEquals(a: String, b: String): Boolean {
        if (a.length != b.length) return false
        var result = 0
        for (i in a.indices) {
            result = result or (a[i].code xor b[i].code)
        }
        return result == 0
    }

    private fun parsePayload(json: String): TokenClaims? {
        val fields = json.trim('{', '}').split(",").associate {
            val (k, v) = it.split(":", limit = 2)
            k.trim().trim('"') to v.trim().trim('"')
        }
        return TokenClaims(
            userId = fields["uid"] ?: return null,
            serviceId = fields["sid"] ?: return null,
            issuedAt = fields["iat"]?.toLongOrNull() ?: return null,
            sessionNonce = fields["nonce"] ?: return null
        )
    }
}

class ChatRateLimiter(
    private val messagesPerMinute: Int = 30,
    private val refillRate: Double = 0.5
) {
    private val buckets = ConcurrentHashMap<String, RateLimitBucket>()
    private val crossServiceCounter = ConcurrentHashMap<String, AtomicLong>()

    fun computeBucketKey(claims: TokenClaims): String {
        val composite = "${claims.userId}:${claims.serviceId}"
        val digest = MessageDigest.getInstance("SHA-256")
        val hash = digest.digest(composite.toByteArray())
        return Base64.getUrlEncoder().withoutPadding().encodeToString(hash).substring(0, 16)
    }

    fun shouldAllowMessage(token: String, channelId: String): RateLimitResult {
        val claims = HmacValidator.validateServiceToken(token)
            ?: return RateLimitResult(allowed = false, reason = "invalid_token")

        val now = Instant.now().epochSecond
        if (now - claims.issuedAt > 300) {
            return RateLimitResult(allowed = false, reason = "token_expired")
        }

        val bucketKey = computeBucketKey(claims)
        val bucket = buckets.computeIfAbsent(bucketKey) {
            RateLimitBucket(messagesPerMinute, refillRate)
        }

        trackCrossServiceUsage(claims)

        if (!bucket.tryConsume()) {
            return RateLimitResult(allowed = false, reason = "rate_limited")
        }

        return RateLimitResult(allowed = true, reason = "ok")
    }

    private fun trackCrossServiceUsage(claims: TokenClaims) {
        val trackingKey = "${claims.userId}:${claims.sessionNonce}"
        crossServiceCounter.computeIfAbsent(trackingKey) { AtomicLong(0) }.incrementAndGet()
    }

    fun getActiveBucketCount(): Int = buckets.size
}

data class RateLimitResult(val allowed: Boolean, val reason: String)

fun main() {
    val limiter = ChatRateLimiter(messagesPerMinute = 5, refillRate = 0.08)
    println("Chat rate limiter initialized with ${limiter.getActiveBucketCount()} active buckets")
}
